const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

/**
 * Money is carried in hundredths of a G so intermediate percentages stay exact:
 * the spec keeps intermediates as fractions and rounds only the final amount,
 * but in binary floating point `100 * 1.1` is 110.00000000000001, which rounds
 * up to 111. Scaling to integers before rounding avoids that drift.
 */
const SUBUNITS_PER_G = 100;
const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);

/** Premiums round up — in the MHPCO's favour. */
const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);

const basePremiumOf = (item: Item): number => {
  return item.type === "sword" ? 100 : 0;
};

const quotePremium = (items: Item[]): number => {
  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const surcharged = toSubunits(policyBase) * (1 + FIRST_INSURANCE_SURCHARGE);

  return toPremiumGold(surcharged + toSubunits(PROCESSING_FEE));
};

